-- Table mini_grammaire_codes : codes de correction
-- Générée depuis ui/test/data/document.json (158 fiches)
-- Mapping : code <- sous_categorie, category <- categorie, description <- regle,
--           detail <- exemple_fautif, example <- exemple_corrige

CREATE TABLE IF NOT EXISTS `mini_grammaire_codes` (
                                                      `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
                                                      `code` varchar(20) NOT NULL,
    `category` varchar(100) NOT NULL,
    `description` text NOT NULL,
    `detail` text DEFAULT NULL,
    `example` text DEFAULT NULL,
    PRIMARY KEY (`id`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

