INSERT INTO `mini_grammaire_codes` (`id`, `code`, `category`, `description`, `detail`, `example`) VALUES
                                                                                                      (1, 'G1.1', 'Orthographe grammaticale', 'Le déterminant s''accorde en genre et en nombre avec le nom.', 'Le monde virtuel constitue, pour certains, un échappatoire à la vie réelle.', 'Le monde virtuel constitue, pour certains, une échappatoire à la vie réelle.'),
                                                                                                      (2, 'G1.1', 'Orthographe grammaticale', 'Le nom s''écrit au singulier ou au pluriel, au masculin ou au féminin, selon le contexte.', 'À cette occasion, vous pourrez vous procurer gratuitement botte et mitaine.', 'À cette occasion, vous pourrez vous procurer gratuitement bottes et mitaines.'),
                                                                                                      (3, 'G1.1', 'Orthographe grammaticale', 'Le complément du nom s''accorde généralement en fonction du sens.', 'J''ai six ans d''expériences dans le domaine de l''éducation à l''enfance.', 'J''ai six ans d''expérience dans le domaine de l''éducation à l''enfance.'),
                                                                                                      (4, 'G1.1', 'Orthographe grammaticale', 'L''adjectif s''accorde en genre et en nombre avec le mot qu''il qualifie.', 'Conscient des impacts d''une tel tragédie, la communauté international a déployé des mesures d''aide exceptionnelle.', 'Consciente des impacts d''une telle tragédie, la communauté internationale a déployé des mesures d''aide exceptionnelles.'),
                                                                                                      (5, 'G1.2', 'Orthographe grammaticale', 'Accord particulier dans le groupe nominal (déterminants numéraux, noms composés, adjectifs de couleur).', 'Les septs couleurs de l''arc-en-ciel : mythe ou réalité?', 'Les sept couleurs de l''arc-en-ciel : mythe ou réalité?'),
                                                                                                      (6, 'G1.2', 'Orthographe grammaticale', 'Accord particulier dans le groupe nominal (déterminants numéraux, noms composés, adjectifs de couleur).', 'Deux pauses-cafés sont prévues pour la journée.', 'Deux pauses-café sont prévues pour la journée.'),
                                                                                                      (7, 'G2', 'Orthographe grammaticale', 'Le pronom s''accorde généralement avec son antécédent.', 'L''hémoglobine qu''elles contiennent se lie à l''oxygène pour acheminer cette dernière à toutes les cellules.', 'L''hémoglobine qu''ils contiennent se lie à l''oxygène pour acheminer ce dernier à toutes les cellules.'),
                                                                                                      (8, 'G3.1', 'Orthographe grammaticale', 'Le verbe conjugué à un temps simple s''accorde avec son sujet. (Trouver le sujet : Qu''est-ce qui ? / Qui est-ce qui ?)', 'Une période de questions est prévue pour ceux d''entre vous qui désirez avoir plus d''informations.', 'Une période de questions est prévue pour ceux d''entre vous qui désirent avoir plus d''informations.'),
                                                                                                      (9, 'G3.2', 'Orthographe grammaticale', 'L''auxiliaire s''accorde avec le sujet du verbe.', 'Le conférencier propose une analyse du manifeste Refus global qu''a rédigé les Automatistes en 1948.', 'Le conférencier propose une analyse du manifeste Refus global qu''ont rédigé les Automatistes en 1948.'),
                                                                                                      (10, 'G3.3', 'Orthographe grammaticale', 'La terminaison d''un verbe à un temps simple suit le modèle de conjugaison de son groupe (annexe I).', 'L''accès à un système d''éducation universel et gratuit contribut à réduire les inégalités sociales.', 'L''accès à un système d''éducation universel et gratuit contribue à réduire les inégalités sociales.'),
                                                                                                      (11, 'G3.4', 'Orthographe grammaticale', 'Le verbe à l''infinitif est invariable (remplacable par « mordre ») et ne doit pas être confondu avec le participe passé.', 'Nous nous intéresserons aux différentes façons de les mettres en pratique.', 'Nous nous intéresserons aux différentes façons de les mettre en pratique.'),
                                                                                                      (12, 'G3.4', 'Orthographe grammaticale', 'Le verbe à l''infinitif est invariable (remplacable par « mordre »).', 'Il faudra augmenté la dose d''amlodipine de 2,5 mg.', 'Il faudra augmenter la dose d''amlodipine de 2,5 mg.'),
                                                                                                      (13, 'G3.5', 'Orthographe grammaticale', 'Le participe présent d''un verbe est invariable.', 'Cette mesure concerne tous les gens visitants le Mexique régulièrement.', 'Cette mesure concerne tous les gens visitant le Mexique régulièrement.'),
                                                                                                      (14, 'G4.1', 'Orthographe grammaticale', 'La terminaison du participe passé dépend du groupe verbal (annexe II).', 'Le concept de mixité sociale a été prit en compte dans le développement de ce nouveau quartier.', 'Le concept de mixité sociale a été pris en compte dans le développement de ce nouveau quartier.'),
                                                                                                      (15, 'G4.2', 'Orthographe grammaticale', 'Le participe passé employé seul s''accorde avec le mot qu''il accompagne (annexe III).', 'Il sera question des produits financiers offert par les différentes institutions bancaires.', 'Il sera question des produits financiers offerts par les différentes institutions bancaires.'),
                                                                                                      (16, 'G4.2', 'Orthographe grammaticale', 'Le participe passé employé seul s''accorde avec le mot qu''il accompagne.', 'Sorti en 1970, les films québécois Deux femmes en or et L''Initiation ont pour thème l''émancipation sexuelle des femmes.', 'Sortis en 1970, les films québécois Deux femmes en or et L''Initiation ont pour thème l''émancipation sexuelle des femmes.'),
                                                                                                      (17, 'G4.3', 'Orthographe grammaticale', 'Le participe passé avec l''auxiliaire être s''accorde avec le sujet (vraie aussi pour les verbes attributifs : demeurer, devenir, paraître, rester, sembler...).', 'Si Elvis Presley et Chuck Berry sont constamment cité comme pionniers du rock américain, d''autres semblent disparu de la mémoire collective.', 'Si Elvis Presley et Chuck Berry sont constamment cités comme pionniers du rock américain, d''autres semblent disparus de la mémoire collective.'),
                                                                                                      (18, 'G4.4', 'Orthographe grammaticale', 'Le participe passé avec l''auxiliaire avoir : s''accorde avec le COD placé devant le verbe; demeure invariable si le COD est après le verbe ou si le verbe n''a pas de COD.', 'La municipalité a investie massivement pour protéger les zones riveraines.', 'La municipalité a investi massivement pour protéger les zones riveraines.'),
                                                                                                      (19, 'G4.4', 'Orthographe grammaticale', 'Le participe passé avec l''auxiliaire avoir : s''accorde avec le COD placé devant le verbe.', 'Les oiseaux qu''elle a vue sont probablement des aigrettes.', 'Les oiseaux qu''elle a vus sont probablement des aigrettes.'),
                                                                                                      (20, 'G4.4', 'Orthographe grammaticale', 'Le participe passé avec l''auxiliaire avoir : demeure invariable si le COD est après le verbe.', 'Alice a parlée à Anna hier.', 'Alice a parlé à Anna hier.'),
                                                                                                      (21, 'G4.5', 'Orthographe grammaticale', 'Le participe passé d''un verbe essentiellement pronominal s''accorde avec le sujet.', 'Vendredi après-midi, neuf étudiants se sont absenté.', 'Vendredi après-midi, neuf étudiants se sont absentés.'),
                                                                                                      (22, 'G4.6', 'Orthographe grammaticale', 'Le participe passé d''un verbe occasionnellement pronominal : s''accorde avec le COD placé devant le verbe; invariable sinon.', 'Ils se sont partagés les heures de gymnase restantes.', 'Ils se sont partagé les heures de gymnase restantes.'),
                                                                                                      (23, 'G4.7', 'Orthographe grammaticale', 'Le participe passé obéit parfois à une règle particulière (auxiliaire avoir suivi d''un infinitif; employé comme préposition).', 'Les tempêtes qu''il y a eues ont causé un ralentissement.', 'Les tempêtes qu''il y a eu ont causé un ralentissement.'),
                                                                                                      (24, 'G5', 'Orthographe grammaticale', 'Une erreur d''homophones se corrige par l''identification de sa catégorie grammaticale ou par un truc de substitution (annexe IV).', 'Ce drame quelle cache depuis vingt ans sera-t-il enfin connu?', 'Ce drame qu''elle cache depuis vingt ans sera-t-il enfin connu?'),
                                                                                                      (25, 'G6.1', 'Orthographe grammaticale', 'La conjonction (ou locution conjonctive) est invariable.', 'Nous étions prêts, saufs que la panne d''électricité a compliqué beaucoup les choses.', 'Nous étions prêts, sauf que la panne d''électricité a compliqué beaucoup les choses.'),
                                                                                                      (26, 'G6.2', 'Orthographe grammaticale', 'L''adverbe, la locution adverbiale ou le mot employé comme adverbe est invariable.', 'Ils travaillent ensembles depuis de nombreuses années.', 'Ils travaillent ensemble depuis de nombreuses années.'),
                                                                                                      (27, 'G6.2', 'Orthographe grammaticale', 'L''adverbe est invariable.', 'La médiatisation du crime, en générale, concerne davantage les crimes graves.', 'La médiatisation du crime, en général, concerne davantage les crimes graves.'),
                                                                                                      (28, 'G6.3', 'Orthographe grammaticale', 'La préposition (ou locution prépositive) est invariable.', 'Ils étaient assis derrières moi au concert.', 'Ils étaient assis derrière moi au concert.'),
                                                                                                      (29, 'G6.4', 'Orthographe grammaticale', 'Certains noms propres sont invariables.', 'Les Simards habitent une petite maison à Joliette.', 'Les Simard habitent une petite maison à Joliette.'),
                                                                                                      (30, 'P1', 'Ponctuation et typographie', 'Un marqueur de relation est généralement suivi d''une virgule en début de phrase, encadré de virgules en milieu de phrase et précédé d''une virgule en fin de phrase.', NULL, 'Tout compte fait, le libéralisme français s''est heurté à la tension entre liberté et égalité.'),
                                                                                                      (31, 'P1', 'Ponctuation et typographie', 'Une virgule est généralement placée devant les coordonnants mais, car, puis, donc, etc.', NULL, 'Ce groupe de recherche a produit des travaux intéressants, mais ses subventions n''ont pas été renouvelées.'),
                                                                                                      (32, 'P1', 'Ponctuation et typographie', 'Les coordonnants et, ou et ni ne sont généralement pas précédés d''une virgule.', NULL, 'La loi prévoit qu''on ne peut ni vous obliger ni vous inciter à changer de pharmacie.'),
                                                                                                      (33, 'P1', 'Ponctuation et typographie', 'Le complément de phrase (facultatif et déplaçable) est suivi d''une virgule en début de phrase, encadré de virgules en milieu de phrase et pas précédé d''une virgule en fin de phrase (sauf concession, restriction ou opposition).', NULL, 'Dans la région du Saguenay-Lac-Saint-Jean, une grande majorité des terrains forestiers sont des forêts publiques.'),
                                                                                                      (34, 'P1', 'Ponctuation et typographie', 'La virgule sépare les éléments d''une énumération, incluant etc.', NULL, 'L''industrie forestière offre des possibilités de carrière dans plusieurs domaines : la récolte, l''aménagement et la transformation.'),
                                                                                                      (35, 'P1', 'Ponctuation et typographie', 'La virgule sépare des phrases juxtaposées.', NULL, NULL),
                                                                                                      (36, 'P1', 'Ponctuation et typographie', 'La virgule est placée devant des éléments qui introduisent une explication, une précision, un commentaire ou un exemple.', NULL, 'Ce passage contient plusieurs noms de lieux, tels que Cape Cod, Québec et Niagara.'),
                                                                                                      (37, 'P1', 'Ponctuation et typographie', 'Un élément mis en relief est encadré de virgules.', NULL, NULL),
                                                                                                      (38, 'P1-Virgule fautive', 'Ponctuation et typographie', 'Le verbe n''est pas séparé de son sujet par une virgule.', 'Dans La Presse, une chroniqueuse critique, le tourisme humanitaire de manière virulente.', 'Dans La Presse, une chroniqueuse critique le tourisme humanitaire de manière virulente.'),
                                                                                                      (39, 'P1-Virgule fautive', 'Ponctuation et typographie', 'Le verbe n''est pas séparé de son complément direct ou indirect par une virgule.', 'C''est l''histoire d''un vieil homme qui accroche, à un ordre social révolu depuis longtemps.', 'C''est l''histoire d''un vieil homme qui accroche à un ordre social révolu depuis longtemps.'),
                                                                                                      (40, 'P1-Virgule fautive', 'Ponctuation et typographie', 'La virgule est fautive lorsque le verbe est séparé de son modificateur (adverbe) ou que le nom ou l''adjectif est séparé d''un complément essentiel.', 'Il est à noter qu''elle parle, très lentement, pour s''assurer d''être comprise.', 'Il est à noter qu''elle parle très lentement pour s''assurer d''être comprise.'),
                                                                                                      (41, 'P2.1', 'Ponctuation et typographie', 'Le point termine la phrase affirmative.', NULL, 'Le point termine la phrase affirmative.'),
                                                                                                      (42, 'P2.2', 'Ponctuation et typographie', 'Le point d''exclamation termine la phrase exclamative.', 'Que cette tempête a été dévastatrice.', 'Que cette tempête a été dévastatrice!'),
                                                                                                      (43, 'P2.3', 'Ponctuation et typographie', 'Le point d''interrogation termine la phrase interrogative directe.', 'Peut-on affirmer que les théories de Freud sont totalement discréditées aujourd''hui.', 'Peut-on affirmer que les théories de Freud sont totalement discréditées aujourd''hui?'),
                                                                                                      (44, 'P2.4', 'Ponctuation et typographie', 'Les points de suspension marquent l''interruption d''un énoncé.', NULL, 'Je l''ai vu à ce moment... Je pense que... Mais peut-être...'),
                                                                                                      (45, 'P3.1', 'Ponctuation et typographie', 'Les deux-points introduisent une citation en discours rapporté direct.', NULL, 'Bertrand Gervais le note aussi : « L''imaginaire de la fin se déploie comme une pensée sur le temps, essentiellement en crise. »'),
                                                                                                      (46, 'P3.2', 'Ponctuation et typographie', 'Les deux-points introduisent une explication, une énumération ou un exemple.', NULL, 'Les feuilles de basilic ne doivent jamais être conservées dans des sachets en plastique : cela occasionne une moisissure prématurée.'),
                                                                                                      (47, 'P3-Deux-points fautifs', 'Ponctuation et typographie', 'Les deux-points ne s''utilisent pas après des mots qui introduisent un exemple ou une énumération (comme, tel, tel que, soit, car...).', 'Nous créerons ensemble toute la journée, soit : de 9 h à 16 h.', 'Nous créerons ensemble toute la journée, soit de 9 h à 16 h.'),
                                                                                                      (48, 'P3-Deux-points fautifs', 'Ponctuation et typographie', 'Les deux-points ne s''utilisent pas pour introduire une citation fusionnée.', 'Il est mentionné que l''évêque porte une : « améthyste grosse comme une noix ».', 'Il est mentionné que l''évêque porte une « améthyste grosse comme une noix ».'),
                                                                                                      (49, 'P4.1', 'Ponctuation et typographie', 'Le point-virgule sépare deux phrases indépendantes étroitement liées par le sens.', NULL, 'Elle a gagné passablement d''argent pour cette seule journée; elle a touché plus de 680 dollars.'),
                                                                                                      (50, 'P4.2', 'Ponctuation et typographie', 'Le point-virgule sépare les éléments d''une énumération verticale.', NULL, 'L''assistant photographe devra participer aux séances photo; ajuster les réglages; sélectionner, redimensionner et renommer les photos; gérer les catalogues.'),
                                                                                                      (51, 'P5.1', 'Ponctuation et typographie', 'Les guillemets français encadrent une citation ou tout mot tiré d''un texte.', NULL, 'Tout le monde connaît cette citation : « On ne voit bien qu''avec le cœur. »'),
                                                                                                      (52, 'P5.2', 'Ponctuation et typographie', 'Les guillemets français encadrent individuellement chaque mot ou expression d''un champ lexical ou chaque fragment énuméré.', NULL, 'Le texte évoque « barreaux », « filets » et « oiseaux » pour illustrer l''enfermement.'),
                                                                                                      (53, 'P5.3', 'Ponctuation et typographie', 'Les guillemets français encadrent un mot appartenant à une langue étrangère, provenant d''un registre différent ou faisant l''objet d''une mise en évidence.', NULL, 'La traduction de l''expression « to be confident » est la source d''erreurs fréquentes.'),
                                                                                                      (54, 'P5.4', 'Ponctuation et typographie', 'Les guillemets anglais encadrent un passage déjà entre guillemets dans un extrait cité.', NULL, '« Leurs refus répétés ne remettaient nullement en question mon talent; au contraire, ils ne faisaient qu''accentuer l''impression que j''avais d''être " difficile ". »'),
                                                                                                      (55, 'P5-Deconseilles', 'Ponctuation et typographie', 'La citation en retrait n''est généralement pas placée entre guillemets.', NULL, NULL),
                                                                                                      (56, 'P6.1', 'Ponctuation et typographie', 'Les crochets encadrent toute modification du texte cité.', NULL, 'Aragon écrit à propos d''un jeune homme qui « courai[t] les filles » (v. 25).'),
                                                                                                      (57, 'P6.2', 'Ponctuation et typographie', 'Les points de suspension entre crochets [...] indiquent des passages coupés d''un texte cité.', NULL, '« La voix du professeur se mit à bourdonner [...]. » (l. 10-12)'),
                                                                                                      (58, 'P6.3', 'Ponctuation et typographie', 'Les crochets sont utilisés pour intercaler un élément à l''intérieur ou à côté d''un passage entre parenthèses.', NULL, 'Plusieurs responsables de la FIFA (Jeffrey Webb [vice-président de la FIFA], Eugenio Figueredo) ont été arrêtés.'),
                                                                                                      (59, 'P6-Deconseilles', 'Ponctuation et typographie', 'Les points de suspension entre crochets ne sont pas utilisés au début ni à la fin d''une citation fusionnée.', 'Pour Nietzsche, « [...] Dieu est mort et avec lui sont morts ses blasphémateurs [...] », ce qui ouvre une autre dimension à la morale.', 'Pour Nietzsche, « Dieu est mort et avec lui sont morts ses blasphémateurs », ce qui ouvre une autre dimension à la morale.'),
                                                                                                      (60, 'P7.1', 'Ponctuation et typographie', 'Les parenthèses encadrent une explication, une précision ou un commentaire sans briser la structure de la phrase.', NULL, 'La cathédrale Notre-Dame d''Amiens (inscrite depuis 1981 au patrimoine mondial de l''UNESCO) est représentative de l''architecture gothique.'),
                                                                                                      (61, 'P7.2', 'Ponctuation et typographie', 'Les parenthèses d''alternative signifient qu''un mot peut s''écrire de deux façons ou qu''on peut choisir entre deux possibilités.', NULL, 'La ville de Beijing (Pékin) est une des villes chinoises de plus de 20 millions d''habitants.'),
                                                                                                      (62, 'P7.3', 'Ponctuation et typographie', 'La référence d''une citation est placée entre parenthèses dans le texte.', NULL, 'Beaudoin-Bégin rappelle : « Une langue ne disparaît pas quand elle s''éloigne de la norme prescriptive, elle disparaît quand elle n''est plus utilisée, point. » (p. 106)'),
                                                                                                      (63, 'P8.1', 'Ponctuation et typographie', 'Le tiret lie des numéros de vers, de lignes ou de pages qui se suivent dans une référence textuelle.', NULL, '(l. 40-43)'),
                                                                                                      (64, 'P8.2', 'Ponctuation et typographie', 'Le tiret signifie le changement d''interlocuteur dans un texte.', NULL, '— Est-ce que le monde est beau? — Cela lui arrive.'),
                                                                                                      (65, 'P8.3', 'Ponctuation et typographie', 'Le tiret insère un passage dans une phrase, un peu comme le feraient des parenthèses.', NULL, 'La maladie de Crohn — une maladie inflammatoire chronique du système digestif — peut entraîner plusieurs autres problèmes de santé.'),
                                                                                                      (66, 'P8.4', 'Ponctuation et typographie', 'Autre emploi du tiret (à vérifier dans un ouvrage de référence).', NULL, NULL),
                                                                                                      (67, 'P9.1', 'Ponctuation et typographie', 'La barre oblique est principalement employée comme signe de division, de séparation ou d''opposition.', NULL, 'Les paronymes conjoncture/conjecture sont la cause de nombreuses erreurs.'),
                                                                                                      (68, 'P9.2', 'Ponctuation et typographie', 'Les barres obliques séparent les vers consécutifs cités.', NULL, '« Selon que vous serez puissant ou misérable, / Les jugements de cour vous rendront blanc ou noir. »'),
                                                                                                      (69, 'P10.1', 'Ponctuation et typographie', 'La retranscription de la ponctuation du texte cité est fidèle au texte original.', NULL, NULL),
                                                                                                      (70, 'P10.2', 'Ponctuation et typographie', 'Les lettres majuscules et minuscules d''un texte cité doivent être respectées.', NULL, NULL),
                                                                                                      (71, 'P10.3', 'Ponctuation et typographie', 'La ponctuation finale d''une phrase ou d''un vers est généralement supprimée dans une citation fusionnée (sauf points de suspension, d''exclamation ou d''interrogation pertinents).', 'La métaphore « Il était ivre, ivre de distances, ivre de départ. » rend compte du désir d''aventure.', 'La métaphore « Il était ivre, ivre de distances, ivre de départ » rend compte du désir d''aventure.'),
                                                                                                      (72, 'P10.4', 'Ponctuation et typographie', 'La ponctuation d''un passage coupé est conservée ou supprimée selon sa pertinence linguistique.', NULL, '« Elle dansait avec ivresse [...] dans une sorte de nuage de bonheur [...]. »'),
                                                                                                      (73, 'P10.5', 'Ponctuation et typographie', 'Dans une citation en discours rapporté direct, la ponctuation finale se place avant le guillemet fermant et il n''y a pas d''autre ponctuation finale.', NULL, '« Tu ne sais rien, Jon Snow. »'),
                                                                                                      (74, 'P10.6', 'Ponctuation et typographie', 'Dans une citation fusionnée, le point final se place à la toute fin de la phrase, après la référence.', 'Selon Le Nouveau Petit Robert, le colonialisme est un système basé sur « l''occupation et l''exploitation de territoires dans l''intérêt du pays colonisateur. » (p. 467)', 'Selon Le Nouveau Petit Robert, le colonialisme est un système basé sur « l''occupation et l''exploitation de territoires dans l''intérêt du pays colonisateur » (p. 467).'),
                                                                                                      (75, 'P10.7', 'Ponctuation et typographie', 'Dans une citation de vers, le dernier vers cité perd sa virgule, ses deux-points ou son point-virgule, et le point final se place après la référence.', 'Dans le poème « À ma fille », Victor Hugo donne ce conseil : « Fais comme moi : vis du monde éloignée; » (v. 2)', 'Dans le poème « À ma fille », Victor Hugo donne ce conseil : « Fais comme moi : vis du monde éloignée » (v. 2).'),
                                                                                                      (76, 'P11.1', 'Ponctuation et typographie', 'La majuscule s''emploie pour le premier mot d''une phrase, les noms propres, les périodes historiques, les titres d''œuvres, les noms de peuples, etc.', NULL, 'Platon, Aristote et Sénèque sont des philosophes de l''Antiquité. Les Grecs et les Romains de cette période ont jeté plusieurs des bases de la civilisation occidentale.'),
                                                                                                      (77, 'P11.2', 'Ponctuation et typographie', 'La minuscule s''emploie pour les noms communs, les adjectifs, les mots qui suivent les deux-points, les courants littéraires, les religions, etc.', 'Les Québécois raffolent des vins Italiens.', 'Les Québécois raffolent des vins italiens.'),
                                                                                                      (78, 'P11.2', 'Ponctuation et typographie', 'La minuscule s''emploie après les deux-points.', 'Ces personnes sont non binaires : Elles s''identifient à la fois comme homme et femme.', 'Ces personnes sont non binaires : elles s''identifient à la fois comme homme et femme.'),
                                                                                                      (79, 'P12.1', 'Ponctuation et typographie', 'La voyelle finale d''un mot s''efface devant un mot commençant par une voyelle ou un h muet.', 'Le temps, si il est clément, nous permettra de terminer la coupe de foin à temps.', 'Le temps, s''il est clément, nous permettra de terminer la coupe de foin à temps.'),
                                                                                                      (80, 'P12.2', 'Ponctuation et typographie', 'L''élision est interdite dans certains cas (à vérifier dans un ouvrage de référence).', NULL, NULL),
                                                                                                      (81, 'P13', 'Ponctuation et typographie', 'Les abréviations s''écrivent conformément à une convention d''écriture.', 'Le 21ième siècle est déjà bien entamé.', 'Le 21e siècle est déjà bien entamé.'),
                                                                                                      (82, 'P14.1', 'Ponctuation et typographie', 'Le titre d''un ouvrage complet est souligné dans une rédaction manuscrite et inscrit en italique dans une rédaction sur traitement de texte.', NULL, 'Robert, dans son essai La stratégie de l''émotion, montre la prédominance de l''affectif.'),
                                                                                                      (83, 'P14.2', 'Ponctuation et typographie', 'Le titre d''une partie d''ouvrage (article, chapitre, poème, chanson, nouvelle...) est placé entre guillemets français.', NULL, 'Je vous propose de lire l''article « En vacances avec Aristote » de Normand Baillargeon.'),
                                                                                                      (84, 'P15.1', 'Ponctuation et typographie', 'Le guillemet ouvrant, la parenthèse ouvrante et le crochet ouvrant peuvent seuls commencer une ligne; tous les autres signes se retrouvent en fin de ligne.', NULL, 'Le cosmonaute Youri Gagarine a sa place dans l''histoire de la conquête de l''espace, mais aussi dans les astres : un cratère lunaire porte son nom.'),
                                                                                                      (85, 'P15.2', 'Ponctuation et typographie', 'Le mot élidé ne peut pas être séparé du mot qui le suit.', 'Nous devions atterrir en milieu d''après-midi, mais l''avion s'' est finalement posé à 21 h.', 'Nous devions atterrir en milieu d''après-midi, mais l''avion s''est finalement posé à 21 h.'),
                                                                                                      (86, 'P16.1', 'Ponctuation et typographie', 'Les mots sont coupés selon leur prononciation, entre deux syllabes, à l''aide d''un trait d''union.', 'Le magazine Forbes a annoncé que Jay-Z est le premier millia-rdnaire du rap.', 'Le magazine Forbes a annoncé que Jay-Z est le premier milliar-daire du rap.'),
                                                                                                      (87, 'P16.2', 'Ponctuation et typographie', 'Autre règle de coupure de mot (à vérifier dans un ouvrage de référence). Certaines coupures sont déconseillées, notamment la coupure du dernier mot d''un paragraphe.', NULL, NULL),
                                                                                                      (88, 'P17.1', 'Ponctuation et typographie', 'Le trait d''union unit le verbe et les pronoms qui le suivent dans une phrase impérative.', NULL, 'Une fois le mélange prêt, laissez-le refroidir au réfrigérateur pendant une heure.'),
                                                                                                      (89, 'P17.2', 'Ponctuation et typographie', 'Le trait d''union unit le sujet et le verbe inversés dans une phrase interrogative.', NULL, 'Saviez-vous que le mot kakistocratie désigne « le pire gouvernement »?'),
                                                                                                      (90, 'P17.3', 'Ponctuation et typographie', 'Le trait d''union unit les particules adverbiales ci et là avec le nom ou le pronom qui les précède.', NULL, 'Ce jour-là, un effondrement des valeurs boursières a déclenché une crise économique mondiale.'),
                                                                                                      (91, 'P17-Trait fautif', 'Ponctuation et typographie', 'Un trait d''union fautif doit être enlevé.', 'Plusieurs d''entre-elles ont refusé de porter plainte.', 'Plusieurs d''entre elles ont refusé de porter plainte.'),
                                                                                                      (92, 'P18.1', 'Ponctuation et typographie', 'Les accents s''emploient ou non selon l''orthographe du mot.', NULL, 'Les lobbys religieux sont extrêmement puissants dans ce pays sud-asiatique.'),
                                                                                                      (93, 'P18.2', 'Ponctuation et typographie', 'Le tréma s''emploie ou non selon l''orthographe du mot.', NULL, 'Il y avait plusieurs ambiguïtés dans le rapport du policier.'),
                                                                                                      (94, 'P18.3', 'Ponctuation et typographie', 'La cédille se place sous le c devant les voyelles a, o, u pour que le c se prononce s.', NULL, 'Les accommodements sont parfois perçus comme des injustices.'),
                                                                                                      (95, 'P19.1', 'Ponctuation et typographie', 'Les nombres inférieurs à 10 s''écrivent généralement en lettres (sauf tableaux, textes scientifiques, statistiques, techniques et langue commerciale).', NULL, 'Veuillez fournir vos avis de cotisation des deux dernières années.'),
                                                                                                      (96, 'P19.2', 'Ponctuation et typographie', 'Les règles d''espacement doivent être respectées dans une rédaction sur traitement de texte.', NULL, 'Le gouvernement rappelle que l''activité physique aide à prévenir les maladies chroniques comme le cancer, le diabète de type 2 et les maladies du cœur.'),
                                                                                                      (97, 'P19.3', 'Ponctuation et typographie', 'Autre erreur de ponctuation ou de typographie (à vérifier dans un ouvrage de référence).', NULL, NULL),
                                                                                                      (98, 'S1.1', 'Syntaxe', 'L''adverbe ne (ou n'') s''emploie avec pas, plus, aucun, jamais, personne, etc. pour former une phrase négative.', 'Le président a jamais cessé de se battre contre l''instauration de tarifs douaniers.', 'Le président n''a jamais cessé de se battre contre l''instauration de tarifs douaniers.'),
                                                                                                      (99, 'S1.2', 'Syntaxe', 'Au maximum deux marqueurs de négation sont utilisés dans une phrase négative.', 'Il n''y a pas personne qui s''est montré intéressé par le poste de gardien de nuit.', 'Il n''y a personne qui s''est montré intéressé par le poste de gardien de nuit.'),
                                                                                                      (100, 'S1.3', 'Syntaxe', 'L''adverbe ne (ou n'') est suivi de la conjonction que quand il signifie « seulement ». Déconseillé avec l''adverbe seulement (pléonasme).', 'Les adeptes du crudivorisme se nourrissent que d''aliments crus.', 'Les adeptes du crudivorisme ne se nourrissent que d''aliments crus.'),
                                                                                                      (101, 'S2', 'Syntaxe', 'Phrase restrictive.', NULL, 'Il n''y a que la prison de Roberval comme établissement de détention.'),
                                                                                                      (102, 'S3.1', 'Syntaxe', 'La phrase complète doit contenir un verbe conjugué.', 'L''art contemporain désigne l''ensemble de la production artistique produite depuis 1945. Succédant ainsi à l''art dit « moderne ».', 'L''art contemporain désigne l''ensemble de la production artistique produite depuis 1945, succédant ainsi à l''art dit « moderne ».'),
                                                                                                      (103, 'S3.2', 'Syntaxe', 'La phrase complète doit contenir un verbe principal.', 'Des études récentes concluent à l''inefficacité des médicaments homéopathiques. Ce qui relance le débat.', 'Des études récentes concluent à l''inefficacité des médicaments homéopathiques, ce qui relance le débat.'),
                                                                                                      (104, 'S3.3', 'Syntaxe', 'La phrase est incomplète quand un sujet est manquant ou qu''un complément obligatoire est manquant : il faut ajouter le ou les mots manquants.', NULL, NULL),
                                                                                                      (105, 'S4.1', 'Syntaxe', 'La préposition doit être choisie en fonction du complément qu''elle introduit.', 'Parmi le chapitre IV, plusieurs hypothèses sont avancées.', 'Dans le chapitre IV, plusieurs hypothèses sont avancées.'),
                                                                                                      (106, 'S4.1', 'Syntaxe', 'La préposition doit être choisie en fonction du complément qu''elle introduit.', 'La partie a été annulée grâce au mauvais temps.', 'La partie a été annulée en raison du mauvais temps.'),
                                                                                                      (107, 'S4.2', 'Syntaxe', 'Une préposition superflue doit être enlevée.', 'Des solutions ont été envisagées afin de pallier à certains problèmes.', 'Des solutions ont été envisagées afin de pallier certains problèmes.'),
                                                                                                      (108, 'S4.3', 'Syntaxe', 'Une préposition manquante doit être ajoutée.', 'La consommation régulière de pornographie peut influer les comportements sexuels.', 'La consommation régulière de pornographie peut influer sur les comportements sexuels.'),
                                                                                                      (109, 'S5.1', 'Syntaxe', 'Les éléments coordonnés doivent avoir une fonction syntaxique équivalente et être compatibles du point de vue du sens.', 'Tristan aime et joue au hockey depuis plusieurs années.', 'Tristan aime le hockey et y joue depuis plusieurs années.'),
                                                                                                      (110, 'S5.2', 'Syntaxe', 'Les éléments énumérés doivent être de la même catégorie grammaticale et avoir la même fonction syntaxique.', 'Une phase maniaque se caractérise par l''accélération du débit de parole, l''hyperactivité ainsi qu''adopter des comportements à risque.', 'Une phase maniaque se caractérise par l''accélération du débit de parole, l''hyperactivité ainsi que l''adoption de comportements à risque.'),
                                                                                                      (111, 'S5.3', 'Syntaxe', 'Les prépositions à, de et en sont généralement répétées devant chaque élément coordonné ou juxtaposé.', 'Les cours de scénarisation et écriture théâtrale seront offerts cet automne.', 'Les cours de scénarisation et d''écriture théâtrale seront offerts cet automne.'),
                                                                                                      (112, 'S6.1', 'Syntaxe', 'Le pronom utilisé doit avoir un antécédent.', 'L''incendie a ravagé presque tout l''immeuble. Ils ont travaillé la nuit entière.', 'L''incendie a ravagé presque tout l''immeuble. Les pompiers ont travaillé la nuit entière.'),
                                                                                                      (113, 'S6.3', 'Syntaxe', 'Le pronom doit être assez près de son antécédent pour que ce dernier soit clairement identifiable.', 'La légalisation de la prostitution ne favorise pas le bien-être des travailleuses du sexe. À la base, elle génère souvent un traumatisme.', 'La légalisation de la prostitution ne favorise pas le bien-être des travailleuses du sexe. À la base, ce travail génère souvent un traumatisme.'),
                                                                                                      (114, 'S6.4', 'Syntaxe', 'Un pronom manquant doit être ajouté.', 'Sa fille lui a emprunté sa tablette et lui a remise seulement trois jours plus tard.', 'Sa fille lui a emprunté sa tablette et la lui a remise seulement trois jours plus tard.'),
                                                                                                      (115, 'S6.5', 'Syntaxe', 'Un pronom superflu doit être enlevé.', 'Dans ce film, on y dresse un portrait de la France sous l''occupation nazie.', 'Dans ce film, on dresse un portrait de la France sous l''occupation nazie.'),
                                                                                                      (116, 'S6.6', 'Syntaxe', 'Le pronom relatif est choisi en fonction de son antécédent.', 'Les vaccins que j''ai besoin sont en pénurie au Canada.', 'Les vaccins dont j''ai besoin sont en pénurie au Canada.'),
                                                                                                      (117, 'S6.7', 'Syntaxe', 'Le pronom personnel est choisi en fonction de son antécédent.', 'La démographie du pays change et les politiques sociales doivent y tenir compte.', 'La démographie du pays change et les politiques sociales doivent en tenir compte.'),
                                                                                                      (118, 'S6.8', 'Syntaxe', 'Un verbe impersonnel commande d''écrire ce qu''il et non ce qui.', 'Ce qui faut remarquer dans cet exemple, c''est l''emploi de nombreux euphémismes.', 'Ce qu''il faut remarquer dans cet exemple, c''est l''emploi de nombreux euphémismes.'),
                                                                                                      (119, 'S7', 'Syntaxe', 'Le rapport temporel entre deux propositions doit être logique.', 'Si les trottoirs seraient déblayés, j''irais travailler à pied.', 'Si les trottoirs étaient déblayés, j''irais travailler à pied.'),
                                                                                                      (120, 'S7', 'Syntaxe', 'Le rapport temporel entre deux propositions doit être logique.', 'Il se peut que vous avez fait confiance à un fraudeur.', 'Il se peut que vous ayez fait confiance à un fraudeur.'),
                                                                                                      (121, 'S8.1', 'Syntaxe', 'Le sujet du verbe au participe présent doit être le même que celui du verbe principal.', 'Étant en rédaction depuis un an, les effets de l''hydroélectricité sont analysés dans le mémoire.', 'Étant en rédaction depuis un an, j''analyse dans le mémoire les effets de l''hydroélectricité.'),
                                                                                                      (122, 'S8.2', 'Syntaxe', 'Le sujet du verbe à l''infinitif doit être le même que celui du verbe principal.', 'Après avoir déposé les enfants à la garderie, l''éducatrice m''a appelé.', 'Après avoir déposé les enfants à la garderie, j''ai reçu un message de l''éducatrice.'),
                                                                                                      (123, 'S8.3', 'Syntaxe', 'L''emploi de l''adjectif doit préserver la logique de la phrase.', 'Audacieuse dans le traitement de ses thèmes, les œuvres de cette autrice sont acclamées par la critique.', 'Audacieuse dans le traitement de ses thèmes, cette autrice est acclamée par la critique.'),
                                                                                                      (124, 'S9.1', 'Syntaxe', 'Certains verbes se conjuguent avec l''auxiliaire être.', 'Il y avait une dizaine de témoins, mais aucun n''a intervenu.', 'Il y avait une dizaine de témoins, mais aucun n''est intervenu.'),
                                                                                                      (125, 'S9.2', 'Syntaxe', 'Certains verbes se conjuguent avec l''auxiliaire avoir.', 'Il faut qu''il est fini son devoir de physique avant demain.', 'Il faut qu''il ait fini son devoir de physique avant demain.'),
                                                                                                      (126, 'S10.1', 'Syntaxe', 'La citation doit être intégrée correctement à la phrase. Il est fautif de juxtaposer ou de coordonner deux citations en discours rapporté direct.', 'De la même façon, la douleur de l''absence se fait sentir : « Je te cherche partout [...]. » et « Tu me manques terriblement. »', 'De la même façon, la douleur de l''absence se fait sentir : « Je te cherche partout [...] Tu me manques terriblement. »'),
                                                                                                      (127, 'S10.2', 'Syntaxe', 'La coupure d''une citation doit être faite pour que la partie restante demeure une phrase complète et syntaxiquement correcte.', NULL, '« Voyons, un beau morceau de terrain planche, dans une vieille paroisse, du terrain sans une souche ni un creux, [...] des animaux gras [...]. »'),
                                                                                                      (128, 'S10.3', 'Syntaxe', 'La retranscription d''un passage cité doit reproduire fidèlement le texte original.', NULL, NULL),
                                                                                                      (129, 'S11.1', 'Syntaxe', 'Le déterminant possessif doit être cohérent avec le nom ou le pronom auquel il se rapporte.', 'La misère de cette famille se remarque à la pauvreté de leur logement.', 'La misère de cette famille se remarque à la pauvreté de son logement.'),
                                                                                                      (130, 'S11.2', 'Syntaxe', 'Le déterminant possessif est fautif s''il y a déjà un pronom marqueur de possession dans la phrase.', 'Elle s''est cassé sa jambe.', 'Elle s''est cassé une jambe.'),
                                                                                                      (131, 'S11.3', 'Syntaxe', 'Le déterminant défini désigne un objet connu, précisé et individualisé.', NULL, NULL),
                                                                                                      (132, 'S11.4', 'Syntaxe', 'Le déterminant démonstratif détermine un objet désigné précisément ou dont il a déjà été question.', NULL, NULL),
                                                                                                      (133, 'S11.5', 'Syntaxe', 'Le même déterminant est généralement répété devant tous les noms d''une énumération.', NULL, NULL),
                                                                                                      (134, 'S11.6', 'Syntaxe', 'Autre erreur dans le choix du déterminant (à vérifier dans un ouvrage de référence).', NULL, NULL),
                                                                                                      (135, 'S12.1', 'Syntaxe', 'L''ajout du mot que après où, quand, comment et pourquoi relève généralement de l''oralité.', 'Le ministre a expliqué pourquoi que le centre correctionnel a été bâti à Roberval.', 'Le ministre a expliqué pourquoi le centre correctionnel a été bâti à Roberval.'),
                                                                                                      (136, 'S12.2', 'Syntaxe', 'Les mots où, quand, comment et pourquoi ne sont pas précédés d''une préposition dans la phrase.', 'Nous l''avons questionné sur comment créer une entreprise dynamique en région éloignée.', 'Nous l''avons questionné sur les façons de créer une entreprise dynamique en région éloignée.'),
                                                                                                      (137, 'S12.3', 'Syntaxe', 'Les locutions qu''est-ce que et qu''est-ce qui ne sont employées que dans une phrase interrogative directe.', 'Ce sera le meilleur moment pour exprimer qu''est-ce qu''on reproche au conseil d''administration.', 'Ce sera le meilleur moment pour exprimer ce qu''on reproche au conseil d''administration.'),
                                                                                                      (138, 'S12.4', 'Syntaxe', 'Les constituants de la phrase doivent s''enchaîner de façon à respecter la syntaxe française.', 'Plusieurs politiques doivent impérativement être revues par le gouvernement, qui concernent les Premiers Peuples.', 'Plusieurs politiques qui concernent les Premiers Peuples doivent impérativement être revues par le gouvernement.'),
                                                                                                      (139, 'S12.5', 'Syntaxe', 'Les consonnes de liaison superflues sont à enlever.', 'Selon les producteurs acéricoles du Québec, ça l''a été une bonne année pour le sirop d''érable.', 'Selon les producteurs acéricoles du Québec, ça a été une bonne année pour le sirop d''érable.'),
                                                                                                      (140, 'S12.6', 'Syntaxe', 'Les lettres euphoniques sont nécessaires pour faciliter certaines prononciations.', 'Donne-en une partie à un organisme communautaire.', 'Donnes-en une partie à un organisme communautaire.'),
                                                                                                      (141, 'S12.7', 'Syntaxe', 'Une phrase contenant une tournure comparative doit mettre en relation des éléments de même nature.', 'Le système de santé australien est comparable au Canada.', 'Le système de santé australien est comparable à celui du Canada.'),
                                                                                                      (142, 'S12.8', 'Syntaxe', 'Dans la locution tel que, l''adjectif tel doit renvoyer à un nom ou à un pronom : c''est comme qui convient lorsque la comparaison porte sur l''ensemble de la phrase principale.', 'Tel que promis, je vous envoie le lien pour accéder à la réunion.', 'Comme promis, je vous envoie le lien pour accéder à la réunion.'),
                                                                                                      (143, 'U1', 'Orthographe d''usage', 'L''orthographe du mot est à vérifier dans le dictionnaire.', 'Ce soir, nous sommes sensés appercevoir des aurores boréales.', 'Ce soir, nous sommes censés apercevoir des aurores boréales.'),
                                                                                                      (144, 'U2', 'Orthographe d''usage', 'L''orthographe de la locution ou de l''expression est à vérifier dans le dictionnaire.', 'Les goélands, les mouettes et les sternes font partis de la famille des laridés.', 'Les goélands, les mouettes et les sternes font partie de la famille des laridés.'),
                                                                                                      (145, 'U3', 'Orthographe d''usage', 'Une erreur de typographie doit être corrigée.', NULL, NULL),
                                                                                                      (146, 'V1', 'Vocabulaire', 'Un mot utilisé dans un sens inapproprié dans le contexte doit être corrigé.', 'Les deux individus ont fait éruption dans le dépanneur vers 23 h 30.', 'Les deux individus ont fait irruption dans le dépanneur vers 23 h 30.'),
                                                                                                      (147, 'V1', 'Vocabulaire', 'Un mot utilisé dans un sens inapproprié dans le contexte doit être corrigé.', 'Le passage cité démontre une métaphore.', 'Le passage cité contient une métaphore.'),
                                                                                                      (148, 'V2', 'Vocabulaire', 'Un calque de l''anglais ou un emprunt à la langue anglaise doit être corrigé.', 'Il a mis l''emphase sur les réussites du modèle économique norvégien.', 'Il a mis l''accent sur les réussites du modèle économique norvégien.'),
                                                                                                      (149, 'V2', 'Vocabulaire', 'Un calque de l''anglais doit être corrigé.', 'Dû aux changements climatiques, la saison des fraises a été beaucoup plus courte cette année.', 'En raison des changements climatiques, la saison des fraises a été beaucoup plus courte cette année.'),
                                                                                                      (150, 'V3', 'Vocabulaire', 'Un enchaînement de mots ou d''expressions qui véhiculent deux fois une même idée doit être corrigé.', 'Vous devez recommencer à nouveau.', 'Vous devez recommencer.'),
                                                                                                      (151, 'V3', 'Vocabulaire', 'Un pléonasme doit être corrigé.', 'L''encan se tiendra ce vendredi prochain au centre communautaire.', 'L''encan se tiendra ce vendredi au centre communautaire.'),
                                                                                                      (152, 'V4', 'Vocabulaire', 'La trop grande récurrence d''un mot (ou d''un groupe de mots) doit être corrigée.', NULL, NULL),
                                                                                                      (153, 'V5', 'Vocabulaire', 'Un barbarisme (mot ou locution existant qui est déformé ou qui n''est pas attesté en français) doit être corrigé.', 'À prime abord, le tatouage des yeux est déconseillé par les professionnels de la santé oculaire.', 'De prime abord, le tatouage des yeux est déconseillé par les professionnels de la santé oculaire.'),
                                                                                                      (154, 'V5', 'Vocabulaire', 'Un barbarisme doit être corrigé.', 'L''hôtel a commandé 1500 têtes d''oreiller.', 'L''hôtel a commandé 1500 taies d''oreiller.'),
                                                                                                      (155, 'V6.1', 'Vocabulaire', 'Les registres familier, populaire et vulgaire ne s''emploient que dans des contextes spécifiques.', 'Il ne pense qu''à lui et se fout complètement de sa famille.', 'Il ne pense qu''à lui et est complètement indifférent à sa famille.'),
                                                                                                      (156, 'V6.2', 'Vocabulaire', 'Le registre littéraire ne s''emploie que dans des contextes spécifiques.', 'Il abhorre leur nonchalance autant que leur arrogance.', 'Il déteste leur nonchalance autant que leur arrogance.'),
                                                                                                      (157, 'V6.3', 'Vocabulaire', 'Le vocabulaire spécialisé s''emploie dans des contextes spécifiques.', 'Nous demandons d''éteindre les téléphones cellulaires en classe, mais les étudiants n''obtempèrent pas.', 'Nous demandons d''éteindre les téléphones cellulaires en classe, mais les étudiants ne se conforment pas.'),
                                                                                                      (158, 'V7', 'Vocabulaire', 'Un archaïsme (vocabulaire appartenant à une époque antérieure) doit être corrigé.', 'Les tentes et les matelas sont fournis, mais pas les couvertes.', 'Les tentes et les matelas sont fournis, mais pas les couvertures.');
